	public static void main(String[] args) throws IOException {
		BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
		int a = Integer.parseInt(tokenizer.nextToken());
		int b = Integer.parseInt(tokenizer.nextToken());
		long l = Long.parseLong(tokenizer.nextToken());
		long r = Long.parseLong(tokenizer.nextToken());

		if (r - l + 1 >= 2 * (a + b)) {
			System.out.println(a <= b ? a + 1 : 2 * a - b);
			return;
		}

		StringBuilder patternBuilder = new StringBuilder();
		for (int i = 0; i < a; i++) {
			patternBuilder.append((char) ('a' + i));
		}

		l--;
		r--;

		TreeSet<Integer> usedLetters = new TreeSet<>();
		int minDifferentLetters = 26;

		for (int firstLetter = 0; firstLetter < 26; firstLetter++) {
			for (int secondLetter = a; secondLetter < 26; secondLetter++) {
				StringBuilder currentStr = new StringBuilder(patternBuilder);
				for (int i = 0; i < b; i++) {
					currentStr.append((char) ('a' + firstLetter));
