					}
					currentStr.append((char) ('a' + nextCharIdx));
					nextCharIdx++;
				}
				for (int i = 0; i < b; i++) {
					currentStr.append((char) ('a' + secondLetter));
				}
				int len = currentStr.length();
				usedLetters.clear();
				for (int i = (int) (l % len); i != (r + 1) % len; i = (i + 1) % len) {
					usedLetters.add(currentStr.charAt(i) - 'a');
				}
				if (usedLetters.size() < minDifferentLetters) {
					minDifferentLetters = usedLetters.size();
				}
			}
		}
		System.out.println(minDifferentLetters);
	}
}
