#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b;
    long long l, r;
    cin >> a >> b >> l >> r;

    if (r - l + 1 >= 2LL * (a + b)) {
        cout << (a <= b ? a + 1 : 2 * a - b) << "\n";
        return 0;
    }

    string pattern;
    for (int i = 0; i < a; i++) {
        pattern += ('a' + i);
    }

    l--;
    r--;

    int minDifferentLetters = 26;

    for (int firstLetter = 0; firstLetter < 26; firstLetter++) {
        for (int secondLetter = a; secondLetter < 26; secondLetter++) {
            string currentStr = pattern;
            for (int i = 0; i < b; i++) {
                currentStr += ('a' + firstLetter);
            }
            set<int> usedLetters;
            for (char c : string(currentStr.end() - a, currentStr.end())) {
                usedLetters.insert(c - 'a');
            }
            int nextCharIdx = 0;
            for (int i = 0; i < a; i++) {
                while (usedLetters.count(nextCharIdx)) {
                    nextCharIdx++;
                }
                currentStr += ('a' + nextCharIdx);
                nextCharIdx++;
            }
            for (int i = 0; i < b; i++) {
                currentStr += ('a' + secondLetter);
            }
            int len = currentStr.length();
            usedLetters.clear();
            for (int i = (int)(l % len); i != (int)((r + 1) % len); i = (i + 1) % len) {
                usedLetters.insert(currentStr[i] - 'a');
            }
            if ((int)usedLetters.size() < minDifferentLetters) {
                minDifferentLetters = usedLetters.size();
            }
        }
    }
    cout << minDifferentLetters << "\n";

    return 0;
}
